<html lang="en">
<head>
<meta charset="UTF-8">
<title>CHIP-8 Emulator</title>
<style>
body{background:#111;color:#ddd;font-family:monospace;margin:0;padding:16px;display:flex;gap:20px;flex-wrap:wrap;justify-content:center}
h1{width:100%;text-align:center;margin:0 0 8px;color:#7f7}
.panel{background:#1c1c1c;border:1px solid #333;border-radius:6px;padding:12px}
