.controls{margin-top:10px;display:flex;gap:8px;flex-wrap:wrap;align-items:center}
button{background:#2a2a2a;color:#eee;border:1px solid #555;border-radius:4px;padding:6px 12px;font-family:inherit;cursor:pointer}
button:hover{background:#3a3a3a}button:disabled{opacity:.4;cursor:default}
