</head>
<body>
<h1>CHIP-8 Emulator</h1>
<div class="panel">
  <canvas id="screen" width="64" height="32"></canvas>
  <div class="controls">
    <button id="run">Run</button><button id="pause">Pause</button>
    <button id="step">Step</button><button id="reset">Reset</button>
    <button id="demo">Load Demo</button>
    <input type="file" id="file" accept=".ch8,.c8,.rom,*/*">
  </div>
  <div class="controls">
    <label>Instructions/frame: <input type="range" id="speed" min="1" max="50" value="10"> <span id="speedv">10</span></label>
    <span>Status: <span id="status">paused</span></span>
  </div>
  <div id="keypad"></div>
  <p style="font-size:12px;color:#999">Demo: move the sprite with W/A/S/D (CHIP-8 keys 5/7/8/9).</p>
</div>
<div class="panel dbg">
  <div>PC: <span id="pc" class="hl"></span> &nbsp; I: <span id="ir" class="hl"></span></div>
  <div>DT: <span id="dt"></span> &nbsp; ST: <span id="st"></span></div>
  <div>Instr: <span id="instr" class="hl"></span></div>
  <h4>Registers</h4><table id="regs"></table>
  <h4>Stack (SP=<span id="sp"></span>)</h4><div id="stack"></div>
</div>
<script>
"use strict";
const FONT=[0xF0,0x90,0x90,0x90,0xF0,0x20,0x60,0x20,0x20,0x70,0xF0,0x10,0xF0,0x80,0xF0,0xF0,0x10,0xF0,0x10,0xF0,
0x90,0x90,0xF0,0x10,0x10,0xF0,0x80,0xF0,0x10,0xF0,0xF0,0x80,0xF0,0x90,0xF0,0xF0,0x10,0x20,0x40,0x40,
0xF0,0x90,0xF0,0x90,0xF0,0xF0,0x90,0xF0,0x10,0xF0,0xF0,0x90,0xF0,0x90,0x90,0xE0,0x90,0xE0,0x90,0xE0,
0xF0,0x80,0x80,0x80,0xF0,0xE0,0x90,0x90,0x90,0xE0,0xF0,0x80,0xF0,0x80,0xF0,0xF0,0x80,0xF0,0x80,0x80];
// Demo ROM (hand-assembled). Moves a ball sprite with keys 5(up) 8(down) 7(left) 9(right).
const DEMO=new Uint8Array([
0x60,0x1C, // 200 LD V0,28
0x61,0x0D, // 202 LD V1,13
0xA2,0x4C, // 204 LD I,0x24C
0xD0,0x15, // 206 DRW V0,V1,5
0x62,0x03, // 208 loop: LD V2,3
0xF2,0x15, // 20A LD DT,V2
0xF3,0x07, // 20C wait: LD V3,DT
0x33,0x00, // 20E SE V3,0
0x12,0x0C, // 210 JP wait
0x64,0x05, // 212 LD V4,5
0xE4,0xA1, // 214 SKNP V4
0x22,0x2C, // 216 CALL up
0x64,0x08, // 218 LD V4,8
0xE4,0xA1, // 21A SKNP V4
0x22,0x34, // 21C CALL down
0x64,0x07, // 21E LD V4,7
0xE4,0xA1, // 220 SKNP V4
0x22,0x3C, // 222 CALL left
0x64,0x09, // 224 LD V4,9
0xE4,0xA1, // 226 SKNP V4
0x22,0x44, // 228 CALL right
0x12,0x08, // 22A JP loop
0xD0,0x15,0x71,0xFF,0xD0,0x15,0x00,0xEE, // 22C up: erase, V1-=1, draw, RET
0xD0,0x15,0x71,0x01,0xD0,0x15,0x00,0xEE, // 234 down
0xD0,0x15,0x70,0xFF,0xD0,0x15,0x00,0xEE, // 23C left
0xD0,0x15,0x70,0x01,0xD0,0x15,0x00,0xEE, // 244 right
0x3C,0x7E,0xFF,0x7E,0x3C                 // 24C sprite
]);

const C={mem:new Uint8Array(4096),V:new Uint8Array(16),I:0,pc:0x200,stack:[],dt:0,st:0,
  gfx:new Uint8Array(64*32),keys:new Array(16).fill(false),waitReg:-1,waitKey:-1,rom:DEMO,halted:false};

function reset(){
  C.mem.fill(0);FONT.forEach((b,i)=>C.mem[0x50+i]=b);
  C.mem.set(C.rom.slice(0,4096-0x200),0x200);
  C.V.fill(0);C.I=0;C.pc=0x200;C.stack=[];C.dt=0;C.st=0;C.gfx.fill(0);C.waitReg=-1;C.waitKey=-1;C.halted=false;
  draw();updateDbg();
}

function disasm(op){
  const x=(op>>8)&15,y=(op>>4)&15,n=op&15,nn=op&255,nnn=op&0xFFF,h=v=>v.toString(16).toUpperCase(),
  X="V"+h(x),Y="V"+h(y);
  switch(op>>12){
    case 0: if(op===0x00E0)return "CLS"; if(op===0x00EE)return "RET"; return "SYS "+h(nnn);
    case 1: return "JP "+h(nnn); case 2: return "CALL "+h(nnn);
    case 3: return `SE ${X}, ${h(nn)}`; case 4: return `SNE ${X}, ${h(nn)}`;
    case 5: return n===0?`SE ${X}, ${Y}`:"???";
    case 6: return `LD ${X}, ${h(nn)}`; case 7: return `ADD ${X}, ${h(nn)}`;
    case 8: return ({0:"LD",1:"OR",2:"AND",3:"XOR",4:"ADD",5:"SUB",6:"SHR",7:"SUBN",14:"SHL"}[n]||"???")+` ${X}, ${Y}`;
    case 9: return n===0?`SNE ${X}, ${Y}`:"???";
    case 10: return "LD I, "+h(nnn); case 11: return "JP V0, "+h(nnn);
    case 12: return `RND ${X}, ${h(nn)}`; case 13: return `DRW ${X}, ${Y}, ${n}`;
    case 14: return nn===0x9E?`SKP ${X}`:nn===0xA1?`SKNP ${X}`:"???";
    case 15: return ({0x07:`LD ${X}, DT`,0x0A:`LD ${X}, K`,0x15:`LD DT, ${X}`,0x18:`LD ST, ${X}`,0x1E:`ADD I, ${X}`,
      0x29:`LD F, ${X}`,0x33:`LD B, ${X}`,0x55:`LD [I], ${X}`,0x65:`LD ${X}, [I]`}[nn])||"???";
  }
}

function step(){
  if(C.halted)return;
  if(C.waitReg>=0){ // FX0A: wait for press then release
    if(C.waitKey<0){const k=C.keys.findIndex(v=>v);if(k>=0)C.waitKey=k;}
    else if(!C.keys[C.waitKey]){C.V[C.waitReg]=C.waitKey;C.waitReg=-1;C.waitKey=-1;}
    return;
  }
  const m=C.mem,V=C.V,op=(m[C.pc]<<8)|m[(C.pc+1)&0xFFF];C.pc=(C.pc+2)&0xFFF;
  const x=(op>>8)&15,y=(op>>4)&15,n=op&15,nn=op&255,nnn=op&0xFFF;let f;
  switch(op>>12){
    case 0: if(op===0x00E0)C.gfx.fill(0);
      else if(op===0x00EE){if(!C.stack.length)return halt("Stack underflow");C.pc=C.stack.pop();}
      break; // 0NNN SYS ignored
    case 1: C.pc=nnn;break;
    case 2: if(C.stack.length>=16)return halt("Stack overflow");C.stack.push(C.pc);C.pc=nnn;break;
    case 3: if(V[x]===nn)C.pc+=2;break;
    case 4: if(V[x]!==nn)C.pc+=2;break;
    case 5: if(V[x]===V[y])C.pc+=2;break;
    case 6: V[x]=nn;break;
    case 7: V[x]=(V[x]+nn)&255;break;
    case 8: switch(n){
      case 0:V[x]=V[y];break; case 1:V[x]|=V[y];break; case 2:V[x]&=V[y];break; case 3:V[x]^=V[y];break;
      case 4:f=V[x]+V[y]>255?1:0;V[x]=(V[x]+V[y])&255;V[15]=f;break;
      case 5:f=V[x]>=V[y]?1:0;V[x]=(V[x]-V[y])&255;V[15]=f;break;
      case 6:f=V[x]&1;V[x]=V[x]>>1;V[15]=f;break;
      case 7:f=V[y]>=V[x]?1:0;V[x]=(V[y]-V[x])&255;V[15]=f;break;
      case 14:f=(V[x]>>7)&1;V[x]=(V[x]<<1)&255;V[15]=f;break;
    }break;
    case 9: if(V[x]!==V[y])C.pc+=2;break;
    case 10: C.I=nnn;break;
    case 11: C.pc=(nnn+V[0])&0xFFF;break;
    case 12: V[x]=Math.floor(Math.random()*256)&nn;break;
    case 13:{const sx=V[x]%64,sy=V[y]%32;let col=0;
      for(let r=0;r<n;r++){const py=sy+r;if(py>=32)break;const b=m[(C.I+r)&0xFFF];
        for(let c=0;c<8;c++){const px=sx+c;if(px>=64)break;
          if(b&(0x80>>c)){const i=py*64+px;if(C.gfx[i])col=1;C.gfx[i]^=1;}}}
      V[15]=col;break;}
    case 14: if(nn===0x9E){if(C.keys[V[x]&15])C.pc+=2;}else if(nn===0xA1){if(!C.keys[V[x]&15])C.pc+=2;}break;
    case 15: switch(nn){
      case 0x07:V[x]=C.dt;break; case 0x0A:C.waitReg=x;C.waitKey=-1;break;
      case 0x15:C.dt=V[x];break; case 0x18:C.st=V[x];break;
      case 0x1E:C.I=(C.I+V[x])&0xFFFF;break; case 0x29:C.I=0x50+(V[x]&15)*5;break;
      case 0x33:m[C.I&0xFFF]=Math.floor(V[x]/100);m[(C.I+1)&0xFFF]=Math.floor(V[x]/10)%10;m[(C.I+2)&0xFFF]=V[x]%10;break;
      case 0x55:for(let i=0;i<=x;i++)m[(C.I+i)&0xFFF]=V[i];break;
      case 0x65:for(let i=0;i<=x;i++)V[i]=m[(C.I+i)&0xFFF];break;
    }break;
  }
}
function halt(msg){C.halted=true;running=false;setStatus("halted: "+msg);}

// Display
const cv=document.getElementById("screen"),ctx=cv.getContext("2d"),img=ctx.createImageData(64,32);
function draw(){for(let i=0;i<2048;i++){const o=i*4,on=C.gfx[i];img.data[o]=on?0x77:0;img.data[o+1]=on?0xFF:0x11;img.data[o+2]=on?0x77:0;img.data[o+3]=255;}ctx.putImageData(img,0,0);}

// Sound
let actx=null,osc=null;
function sound(on){
  if(on&&!osc){try{actx=actx||new (window.AudioContext||window.webkitAudioContext)();osc=actx.createOscillator();const g=actx.createGain();g.gain.value=0.05;osc.type="square";osc.frequency.value=440;osc.connect(g).connect(actx.destination);osc.start();}catch(e){osc=null;}}
  else if(!on&&osc){osc.stop();osc=null;}
}

// Debugger
const $=id=>document.getElementById(id),hx=(v,w)=>v.toString(16).toUpperCase().padStart(w,"0");
function updateDbg(){
  const op=(C.mem[C.pc]<<8)|C.mem[(C.pc+1)&0xFFF];
  $("pc").textContent=hx(C.pc,3);$("ir").textContent=hx(C.I,3);$("dt").textContent=C.dt;$("st").textContent=C.st;
  $("instr").textContent=hx(op,4)+"  "+disasm(op)+(C.waitReg>=0?"  (waiting for key)":"");
  let h="";for(let r=0;r<4;r++){h+="<tr>";for(let c=0;c<4;c++){const i=r*4+c;h+=`<td>V${hx(i,1)}=${hx(C.V[i],2)}</td>`;}h+="</tr>";}
  $("regs").innerHTML=h;$("sp").textContent=C.stack.length;
  $("stack").innerHTML=C.stack.length?C.stack.map((a,i)=>`${i}: ${hx(a,3)}`).join("<br>"):"(empty)";
}
function setStatus(s){$("status").textContent=s;}

// Main loop
let running=false,ipf=10,last=performance.now(),acc=0;
function frame(now){
  acc+=now-last;last=now;if(acc>200)acc=200;
  while(acc>=1000/60){acc-=1000/60;
    if(running){for(let i=0;i<ipf&&running;i++)step();
      if(C.dt>0)C.dt--;if(C.st>0)C.st--;}
  }
  sound(running&&C.st>0);draw();updateDbg();requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

// Controls
$("run").onclick=()=>{if(C.halted)return;running=true;setStatus("running");};
$("pause").onclick=()=>{running=false;setStatus("paused");};
$("step").onclick=()=>{running=false;step();if(!C.halted)setStatus("paused (stepped)");draw();updateDbg();};
$("reset").onclick=()=>{const r=running;reset();running=r;setStatus(r?"running":"paused");};
$("demo").onclick=()=>{C.rom=DEMO;reset();running=true;setStatus("running");};
$("speed").oninput=e=>{ipf=+e.target.value;$("speedv").textContent=ipf;};
$("file").onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();
  r.onload=()=>{C.rom=new Uint8Array(r.result);reset();running=true;setStatus("running: "+f.name);e.target.blur();};r.readAsArrayBuffer(f);};

// Keypad: layout 123C/456D/789E/A0BF -> keyboard 1234/QWER/ASDF/ZXCV
const LAYOUT=[1,2,3,12,4,5,6,13,7,8,9,14,10,0,11,15],KB="1234QWERASDFZXCV",keyMap={},els=[];
LAYOUT.forEach((k,i)=>{keyMap[KB[i].toLowerCase()]=k;const d=document.createElement("div");d.className="key";
  d.innerHTML=`<b>${hx(k,1)}</b><span>${KB[i]}</span>`;
  const up=()=>setKey(k,false);d.onmousedown=ev=>{ev.preventDefault();setKey(k,true);};d.onmouseup=up;d.onmouseleave=up;
  d.ontouchstart=ev=>{ev.preventDefault();setKey(k,true);};d.ontouchend=up;
  els[k]=d;$("keypad").appendChild(d);});
function setKey(k,v){C.keys[k]=v;els[k].classList.toggle("down",v);}
document.addEventListener("keydown",e=>{const k=keyMap[e.key.toLowerCase()];if(k!==undefined){e.preventDefault();setKey(k,true);}});
document.addEventListener("keyup",e=>{const k=keyMap[e.key.toLowerCase()];if(k!==undefined){e.preventDefault();setKey(k,false);}});
window.addEventListener("blur",()=>{for(let k=0;k<16;k++)setKey(k,false);});

reset();running=true;setStatus("running");
</script>
</body>
</html>
